#!/bin/zsh
# Build the kit zip. Usage: scripts/build_kit.sh [out.zip]  (default ~/Downloads/claude-missing-features-kit.zip)
cd "$(dirname "$0")/.." || exit 1
OUT="${1:-$HOME/Downloads/claude-missing-features-kit.zip}"; mkdir -p "$(dirname "$OUT")"; OUT="$(cd "$(dirname "$OUT")" && pwd)/$(basename "$OUT")";   # absolute: we cd into the staging dir before zipping
 ST=$(mktemp -d)/kit; mkdir -p "$ST/scripts" "$ST/remotion/src" "$ST/remotion/public/img" "$ST/templates"
cp MASTER_SPEC.md ENVIRONMENT.md nav.js architecture.html pipeline.html .gitignore "$ST/"; cp -r pipeline "$ST/"; rm -rf "$ST/pipeline/node_modules"; mkdir -p "$ST/evals"; cp evals/spec_questions.json "$ST/evals/"; echo "window.AZURE_LINKS = {};" > "$ST/azure_links.js"; mkdir -p "$ST/assets"; for f in edl_decisions chapters audio_fixes exports changelog subtitle_issues; do echo "[]" > "$ST/assets/$f.json"; done; : > "$ST/subtitles.srt"; echo WEBVTT > "$ST/subtitles.vtt"; echo "window.EXPORTS = [];" > "$ST/exports.js"; echo "window.CHAPTERS = {\"src\":[],\"exp\":[]};" > "$ST/chapters.js"; cp kit/okr.template.json "$ST/assets/okr.json"; cp kit/publish.template.json "$ST/assets/publish.json"; python3 -c "import json;d=json.load(open('assets/timings.json'));d['started']='';d['recordings_done']='';json.dump(d,open('$ST/assets/timings.json','w'),indent=1,ensure_ascii=False)"; cp kit/variants.template.json "$ST/remotion/src/variants.json"; echo "{}" > "$ST/assets/export_checks.json"; mkdir -p "$ST/assets/maps"; cp kit/KIT_README.md "$ST/README.md"; cp kit/new-video.sh "$ST/"
cp scripts/{sync_clips.py,render_base.sh,build_subs.py,find_repeats.py,build_site.py,serve.sh,pull_kit.sh,build_kit.sh,build_blurs.py,ocr_frames.swift,build_base.py,ocr_all.sh,find_personal_windows.py,verify_export.py,report.py,pipeline.sh,build_architecture.py,check_env.sh,denoise_audio.py,build_edl.py,build_chapters.py,build_all.sh,check_site.py,backup_drive.sh,measure_video.py,build_okr.py,build_artifacts.py,build_publish.py,build_timeline.py,upload_exports.py,upload_source.py,setup_azure_exports.sh,render_export.sh,register_export.py,check_reuse.sh,check_subtitles.py,build_script.py,build_changelog.py,build_toc.py,build_readme.py,build_pipeline_diagram.py,eval_spec.py} "$ST/scripts/"
cp remotion/{package.json,package-lock.json,tsconfig.json,remotion.config.ts} "$ST/remotion/"
cp remotion/src/*.ts remotion/src/*.tsx "$ST/remotion/src/"; echo '[]' > "$ST/remotion/src/cuts.json"; echo '[]' > "$ST/remotion/src/subs.json"
echo '{"_doc":"source seconds; x,y,w,h in 1920x1080 px","intro_card":{"from":0,"to":0},"slides":[],"blurs":[],"speedups":[],"images":[]}' > "$ST/remotion/src/overlays.json"; echo 'window.EXPORT_MAP = null;' > "$ST/export_map.js"; echo '{"title":"{{TITLE}}","slug":"{{SLUG}}","brand":"{{TITLE}}","thumb":{"line1":"{{TITLE}}","line2":""},"community":{"name":"","platform":"","url":"","display":""},"links":[{"label":"☁️ Azure Storage","url":"https://portal.azure.com/#browse/Microsoft.Storage%2FStorageAccounts"},{"label":"🔑 Azure Key Vault","url":"https://portal.azure.com/#browse/Microsoft.KeyVault%2Fvaults"}],"reuse_allow":[],"sensitive_keywords":[],"personal_app_patterns":[],"verify_app_patterns":[],"caption_fixes":[]}' > "$ST/remotion/src/project.json"; echo "window.PROJECT = null;" > "$ST/project.js"; touch "$ST/remotion/public/.gitkeep" "$ST/remotion/public/img/.gitkeep"
cp kit/templates/* "$ST/templates/"; python3 - "$ST" <<'PY'
import sys,re,pathlib
st=pathlib.Path(sys.argv[1]); h=pathlib.Path('player.html').read_text()
h=re.sub(r'const C=\[\[.*?\]\]; // source seconds','const C=[]; // [[source seconds,"chapter"],...]',h,flags=re.S)
h=re.sub(r'<tr><td>Edits</td>.*?</tr>','<tr><td>Edits</td><td>none</td><td>{{EDITS}}</td></tr>',h,flags=re.S)
(st/'templates'/'player.html').write_text(h)
PY
 echo 'window.SUBS = [];' > "$ST/subs.js"
rm -f "$OUT"; (cd "$ST" && zip -qr "$OUT" .); echo "built $OUT ($(du -h "$OUT" | cut -f1)), $(unzip -Z1 "$OUT" | wc -l | tr -d ' ') files"
